-- The IDEA Club: the first Travel Kit routes (15 routes, 78 lines), from the
-- programs handover's visa research for Iraqi ordinary passports, checked
-- 2026-11-04 (migration 20270327000000_travel_kit.sql). Every route lands as a
-- draft: nothing appears publicly until an editor checks and publishes it in
-- Staff → Club → Travel.
--
-- Each line keeps its source and how sure it is: "official" when the
-- responsible government, its mission in Iraq or its appointed visa centre
-- says it; "secondary" for media or commercial pages; "unconfirmed" when it
-- comes from the same country's mission elsewhere, or is a question to ask.
-- Anything the research could not source is a question, never a requirement.
--
-- Safe to run again. A route is matched by slug and is only rewritten, with
-- its lines, while it is still the import's own untouched draft: its
-- `updated_at` equals its `created_at`, and every line was written in the same
-- transaction and never changed. Any edit in Staff, to the route or to one of
-- its lines, or an added line, makes the import leave it alone. A route an
-- editor deleted comes back on a re-run; retire it instead.
do $do$
declare
  item jsonb;
  entry jsonb;
  found_row public.travel_routes;
  route uuid;
  added integer := 0;
  updated integer := 0;
  kept integer := 0;
  lines_written integer := 0;
  pos integer;
begin
  for item in
    select value from jsonb_array_elements($json$[
{"slug": "china-short-youth-camp", "country": "CN", "visa_ar": "تأشيرة لمخيم شبابي قصير (الفئة غير مؤكدة)", "visa_en": "Visa for a short youth camp (category not confirmed)", "apply_at_ar": "القسم القنصلي في سفارة الصين لدى العراق، محلة 929، زقاق 25، بناية 33، عرصات الهندية، بغداد. من الاثنين إلى الخميس، من 9:30 إلى 15:30، عدا العطل. تُسلَّم الأوراق هناك، ولا يُذكر نظام للحجز، وقد تُطلب مقابلة. أربيل: غير مؤكد.", "apply_at_en": "Consular Office of the Chinese Embassy in Iraq, Mahala 929, Zukak 25, Building 33, Arasat Al-Hindia, Baghdad. Monday to Thursday, 9:30 to 15:30, except holidays. Materials are handed in there; no booking system is described, and an interview may be requested. Erbil: not confirmed.", "ask_ar": "استفسارات التأشيرة في السفارة: 00964-7700811360، baghdad@csm.mfa.gov.cn", "ask_en": "Visa enquiries at the embassy: 00964-7700811360, baghdad@csm.mfa.gov.cn", "note_ar": "ثقة منخفضة. تتولى السفارة إجراءات التأشيرة في بغداد، لكن لم تذكر أي صفحة قرأناها القاعدة الخاصة بجوازات السفر العراقية، ولم تُقرأ قائمة الوثائق. تستغرق المعاملة 5 أيام عمل أو أكثر (صفحة السفارة بتاريخ 2023-05-10). انتهت التخفيضات في الرسوم والإعفاء من البصمات التي نُشرت عنها أخبار في 2023 و2024.", "note_en": "Low confidence. The embassy runs a visa procedure in Baghdad, but no page we read states the rule for Iraqi passports, and its visa checklist was not read. Processing takes 5 or more working days (embassy page dated 2023-05-10). Reports of lower fees and fingerprint exemptions in 2023 and 2024 have ended.", "checked_on": "2026-11-04", "lines": [{"kind": "question", "doc_key": null, "title_en": "Which visa category and document list apply", "title_ar": "ما فئة التأشيرة وما قائمة الوثائق المطلوبة", "detail_en": "Ask the embassy which category a short youth camp uses and for its checklist. The Visas section of its website was not read.", "detail_ar": "اسأل السفارة عن الفئة التي يندرج تحتها المخيم الشبابي القصير وعن قائمة وثائقها. لم يُقرأ قسم التأشيرات في موقعها.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://iq.china-embassy.gov.cn/eng/lsyw/sqfs/", "checked_on": "2026-11-04"}, {"kind": "task", "doc_key": null, "title_en": "Pay the visa fee at Trade Bank of Iraq", "title_ar": "ادفع رسم التأشيرة في المصرف العراقي للتجارة", "detail_en": "When you hand in your papers you get a pick-up form in three copies; the second copy shows the fee. Pay at the Trade Bank of Iraq, Al-Masbah branch (Hay Babel, Street 17, Building 41, Baghdad; Sunday to Thursday, 8:00 to 15:00), then bring the copy and the bank voucher back to collect the visa. The amount is not confirmed.", "detail_ar": "عند تسليم الأوراق تستلم استمارة استلام من ثلاث نسخ، وتظهر الرسوم على النسخة الثانية. ادفع في المصرف العراقي للتجارة، فرع المسبح (حي بابل، شارع 17، بناية 41، بغداد؛ من الأحد إلى الخميس، من 8:00 إلى 15:00)، ثم أعد النسخة ووصل المصرف لاستلام التأشيرة. المبلغ غير مؤكد.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://iq.china-embassy.gov.cn/eng/lsyw/sqfs/", "checked_on": "2026-11-04"}]},
{"slug": "china-student", "country": "CN", "visa_ar": "تأشيرة دراسة («X1» أو «X2»)", "visa_en": "Student visa (X1 or X2)", "apply_at_ar": "القسم القنصلي في سفارة الصين لدى العراق، محلة 929، زقاق 25، بناية 33، عرصات الهندية، بغداد. من الاثنين إلى الخميس، من 9:30 إلى 15:30، عدا العطل. تُسلَّم الأوراق هناك، ولا يُذكر نظام للحجز، وقد تُطلب مقابلة. أربيل: غير مؤكد.", "apply_at_en": "Consular Office of the Chinese Embassy in Iraq, Mahala 929, Zukak 25, Building 33, Arasat Al-Hindia, Baghdad. Monday to Thursday, 9:30 to 15:30, except holidays. Materials are handed in there; no booking system is described, and an interview may be requested. Erbil: not confirmed.", "ask_ar": "استفسارات التأشيرة في السفارة: 00964-7700811360، baghdad@csm.mfa.gov.cn", "ask_en": "Visa enquiries at the embassy: 00964-7700811360, baghdad@csm.mfa.gov.cn", "note_ar": "ثقة منخفضة. لم تُقرأ قواعد السفارة لتأشيرتي «X1» و«X2». تستغرق المعاملة 5 أيام عمل أو أكثر (رقم عام، وليس خاصًا بتأشيرات الدراسة).", "note_en": "Low confidence. The embassy's rules for X1 and X2 visas were not read. Processing takes 5 or more working days (a general figure, not specific to student visas).", "checked_on": "2026-11-04", "lines": [{"kind": "question", "doc_key": null, "title_en": "The student visa document list", "title_ar": "قائمة وثائق تأشيرة الدراسة", "detail_en": "No X1 or X2 checklist was read. Ask the embassy, or read the Visas section of its website.", "detail_ar": "لم تُقرأ قائمة وثائق «X1» أو «X2». اسأل السفارة، أو اقرأ قسم التأشيرات في موقعها.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://iq.china-embassy.gov.cn/eng/lsyw/sqfs/", "checked_on": "2026-11-04"}, {"kind": "task", "doc_key": null, "title_en": "Pay the visa fee at Trade Bank of Iraq", "title_ar": "ادفع رسم التأشيرة في المصرف العراقي للتجارة", "detail_en": "When you hand in your papers you get a pick-up form in three copies; the second copy shows the fee. Pay at the Trade Bank of Iraq, Al-Masbah branch (Hay Babel, Street 17, Building 41, Baghdad; Sunday to Thursday, 8:00 to 15:00), then bring the copy and the bank voucher back to collect the visa. The amount is not confirmed.", "detail_ar": "عند تسليم الأوراق تستلم استمارة استلام من ثلاث نسخ، وتظهر الرسوم على النسخة الثانية. ادفع في المصرف العراقي للتجارة، فرع المسبح (حي بابل، شارع 17، بناية 41، بغداد؛ من الأحد إلى الخميس، من 8:00 إلى 15:00)، ثم أعد النسخة ووصل المصرف لاستلام التأشيرة. المبلغ غير مؤكد.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://iq.china-embassy.gov.cn/eng/lsyw/sqfs/", "checked_on": "2026-11-04"}]},
{"slug": "tunisia-visa-waiver", "country": "TN", "visa_ar": "دون تأشيرة للسياحة حتى 15 يومًا (حسب الأخبار، غير مؤكد)", "visa_en": "No visa for tourism, up to 15 days (reported, not confirmed)", "apply_at_ar": "لا يوجد طلب في ظل الإعفاء. التأشيرات لأغراض أخرى أو لإقامة أطول: غير مؤكدة.", "apply_at_en": "No application under the waiver. Visas for other purposes or longer stays: not confirmed.", "ask_ar": "سفارة أو قنصلية تونسية، ولا سيما إذا كنت مسافرًا مؤديًا أو مندوبًا مدعوًا.", "ask_en": "A Tunisian embassy or consulate, especially if you are going as a performer or invited delegate.", "note_ar": "ثقة متوسطة إلى منخفضة. نقلت وسائل الإعلام في حزيران 2024 أن حاملي جوازات السفر العراقية العادية لا يحتاجون إلى تأشيرة للسياحة لمدة تصل إلى 15 يومًا مرة كل 180 يومًا. لم تُقرأ أي صفحة حكومية تونسية، ولم نجد تأكيدًا لعام 2026. ولم يتأكد هل تُعد المشاركة في مهرجان سياحةً.", "note_en": "Medium-low confidence. Media reported in June 2024 that holders of ordinary Iraqi passports need no visa for tourism, for up to 15 days once every 180 days. No Tunisian government page was read and no 2026 confirmation was found. Whether taking part in a festival counts as tourism is not confirmed.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Ordinary Iraqi passport", "title_ar": "جواز سفر عراقي عادي", "detail_en": "Reported by Rudaw. The validity rule is not confirmed.", "detail_ar": "حسب رووداو. قاعدة الصلاحية غير مؤكدة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "secondary", "source_url": "https://rudaw.net/english/world/15062024", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "hotel_booking", "title_en": "Confirmed hotel reservation", "title_ar": "حجز فندقي مؤكد", "detail_en": "Booked before travel. Reported by Rudaw.", "detail_ar": "محجوز قبل السفر. حسب رووداو.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "secondary", "source_url": "https://rudaw.net/english/world/15062024", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "return_ticket", "title_en": "Return ticket", "title_ar": "تذكرة العودة", "detail_en": "Reported by Rudaw.", "detail_ar": "حسب رووداو.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "secondary", "source_url": "https://rudaw.net/english/world/15062024", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "Does a festival count as tourism", "title_ar": "هل تُعد المشاركة في مهرجان سياحة", "detail_en": "Ask a Tunisian mission before you travel if you are performing or invited as a delegate.", "detail_ar": "اسأل بعثة تونسية قبل السفر إذا كنت ستؤدي أو كنت مدعوًا مندوبًا.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://rudaw.net/english/world/15062024", "checked_on": "2026-11-04"}]},
{"slug": "turkiye-short-visit", "country": "TR", "visa_ar": "زيارة قصيرة: دون تأشيرة لمن هم دون 15 أو فوق 50؛ تأشيرة للأعمار من 15 إلى 50", "visa_en": "Short visit: no visa under 15 or over 50; a visa for ages 15 to 50", "apply_at_ar": "يمكن لمن أعمارهم من 15 إلى 50 ويحملون تأشيرة أو إقامة سارية من شنغن أو الولايات المتحدة أو المملكة المتحدة أو أيرلندا الحصول على تأشيرة إلكترونية لدخول واحد لمدة شهر من evisa.gov.tr بشروط. ويقدّم الآخرون عبر سفارة أو قنصلية تركية. وقالت القنصلية العامة في أربيل في 2018 إن الطلبات تُقدَّم عبر في إف إس غلوبال فقط؛ ولم يتأكد المسار الحالي.", "apply_at_en": "Ages 15 to 50 with a valid Schengen, US, UK or Ireland visa or residence permit may get a single-entry, one-month e-Visa at evisa.gov.tr, under conditions. Everyone else applies through a Turkish embassy or consulate. The Consulate General in Erbil said in 2018 that applications go only through VFS Global; the current route was not confirmed.", "ask_ar": "القنصلية التركية العامة في أربيل أو السفارة التركية في بغداد.", "ask_en": "The Turkish Consulate General in Erbil or the Turkish Embassy in Baghdad.", "note_ar": "ثقة متوسطة: قاعدة التأشيرة من وزارة الخارجية التركية، أما مسار التقديم وقائمة الوثائق فضعيفان. يمكن لمن هم دون 15 وفوق 50 البقاء حتى 90 يومًا في كل 180 يومًا دون تأشيرة. الرسوم ومدة المعاملة غير مؤكدة من صفحة رسمية.", "note_en": "Medium confidence: the visa rule comes from Türkiye's Ministry of Foreign Affairs; the application route and document list are weak. Under 15 and over 50 may stay up to 90 days in any 180 without a visa. Fees and processing time are not confirmed by an official page.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Valid at least 60 days beyond your stay: for a 90-day stay, 150 days of validity on entry.", "detail_ar": "صالح لمدة 60 يومًا على الأقل بعد انتهاء إقامتك: لإقامة 90 يومًا يلزم أن يكون صالحًا 150 يومًا عند الدخول.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "third_country_visa", "title_en": "Schengen, US, UK or Ireland visa or residence permit", "title_ar": "تأشيرة أو إقامة من شنغن أو الولايات المتحدة أو المملكة المتحدة أو أيرلندا", "detail_en": "Only for the e-Visa route, ages 15 to 50.", "detail_ar": "لمسار التأشيرة الإلكترونية فقط، للأعمار من 15 إلى 50.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "Photos, accommodation, funds and itinerary", "title_ar": "الصور والسكن والأموال وخط الرحلة", "detail_en": "One low-quality report lists these for a sticker visa. Confirm the list with the mission or the visa centre.", "detail_ar": "يذكرها تقرير واحد ضعيف لتأشيرة الملصق. تأكد من القائمة لدى البعثة أو مركز التأشيرات.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "secondary", "source_url": "https://raillynews.com/2026/09/grand-opening-of-the-new-turkey-visa-center-in-erbil/", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "Consent for travellers under 18", "title_ar": "موافقة الوالدين لمن هم دون 18", "detail_en": "Under 15 need no visa, but the consent or guardian papers they need are not confirmed.", "detail_ar": "لا يحتاج من هم دون 15 إلى تأشيرة، لكن أوراق الموافقة أو الولاية المطلوبة غير مؤكدة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "unconfirmed", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}]},
{"slug": "turkiye-student", "country": "TR", "visa_ar": "تأشيرة دراسة من بعثة تركية (للأعمار من 15 إلى 50)", "visa_en": "Student visa from a Turkish mission (ages 15 to 50)", "apply_at_ar": "أقرب سفارة أو قنصلية تركية؛ فالتأشيرة الإلكترونية للسياحة أو الأعمال فقط. وقالت القنصلية العامة في أربيل في 2018 إن الطلبات تُقدَّم عبر في إف إس غلوبال؛ ولم نتمكن من فتح صفحة الطلاب الحالية.", "apply_at_en": "The nearest Turkish embassy or consulate; e-Visas are for tourism or business only. The Consulate General in Erbil said in 2018 that applications go through VFS Global; the current VFS student page could not be opened.", "ask_ar": "القنصلية التركية العامة في أربيل أو السفارة التركية في بغداد.", "ask_en": "The Turkish Consulate General in Erbil or the Turkish Embassy in Baghdad.", "note_ar": "ثقة منخفضة. قائمة وثائق الطلاب والرسوم ومدة المعاملة غير مؤكدة. ولم يُذكر هل يمكن لمن هم دون 15 أو فوق 50 الدراسة دون تأشيرة.", "note_en": "Low confidence. The student document list, fees and processing time are not confirmed. It is not stated whether under 15 or over 50 may study without a visa.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Valid at least 60 days beyond your stay.", "detail_ar": "صالح لمدة 60 يومًا على الأقل بعد انتهاء إقامتك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "The student document list", "title_ar": "قائمة وثائق الطلاب", "detail_en": "Not confirmed. Ask the mission or the visa centre for it.", "detail_ar": "غير مؤكدة. اطلبها من البعثة أو من مركز التأشيرات.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}, {"kind": "task", "doc_key": null, "title_en": "Register with the police on arrival", "title_ar": "سجّل لدى الشرطة عند الوصول", "detail_en": "Students register with the local police when they arrive, whatever the visa's validity.", "detail_ar": "يسجّل الطلبة لدى الشرطة المحلية عند وصولهم، مهما كانت صلاحية التأشيرة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa", "checked_on": "2026-11-04"}]},
{"slug": "czechia-study", "country": "CZ", "visa_ar": "تأشيرة طويلة الأمد («D») للدراسة", "visa_en": "Long-term (D) visa for study", "apply_at_ar": "القنصلية العامة للتشيك في أربيل، للمتقدمين من كل العراق؛ وتحيل السفارة في بغداد حاملي الجوازات العادية إليها. الحجز بالإيميل فقط إلى erbil.visa@mzv.gov.cz: اسمك الكامل في العنوان، وفي نص الرسالة اسمك كما في الجواز وتاريخ الميلاد ورقم الجواز والغرض ووسائل التواصل، ومرفقات بصيغة پي دي إف حجمها الكلي 4 ميگابايت: صفحة بيانات الجواز وإثبات الغرض. رسالة واحدة لكل متقدم، دون وكالات أو طلبات مشتركة أو روابط تخزين سحابي، ويجب أن تطابق البيانات المرفقات تمامًا. نحو 5 مواعيد للإقامة الطويلة كل أسبوع حسب ترتيب الوصول. وفوات الموعد يعني البدء من جديد.", "apply_at_en": "Consulate General of the Czech Republic in Erbil, for applicants from all of Iraq; the Embassy in Baghdad refers ordinary passports there. Book by email only, to erbil.visa@mzv.gov.cz: your full name as the subject; in the body your name as in the passport, date of birth, passport number, purpose and contacts; attached as PDFs, 4 MB in all, the passport data page and proof of purpose. One email per applicant, no agencies, joint requests or cloud links; details must match the attachments exactly. About 5 long-term slots a week, in order received. A missed appointment means starting over.", "ask_ar": "القنصلية التشيكية العامة في أربيل: erbil.visa@mzv.gov.cz", "ask_en": "The Czech Consulate General in Erbil: erbil.visa@mzv.gov.cz", "note_ar": "ثقة متوسطة: مسار أربيل وقواعدها من صفحات التشيك الرسمية؛ أما المبالغ ومقاسات الصور فمن بعثات تشيكية أخرى وغير مؤكدة لأربيل. قد يستغرق القرار حتى 60 يومًا، ولا تعطي القنصلية أي تحديثات خلالها. الرسم غير مؤكد (2,500 كرونة تشيكية في بعثة تل أبيب، و103 يورو في صفحة لأربيل انتهت في 2023) ويُدفع نقدًا باليورو.", "note_en": "Medium confidence: the Erbil route and rules come from Czech official pages; amounts and photo sizes come from other Czech missions and are not confirmed for Erbil. The decision can take up to 60 days, and the consulate gives no updates meanwhile. The fee is not confirmed (CZK 2,500 at the Tel Aviv mission; EUR 103 on an Erbil page that expired in 2023) and is paid in cash in euros.", "checked_on": "2026-11-04", "lines": [{"kind": "task", "doc_key": null, "title_en": "Book the appointment by email", "title_ar": "احجز الموعد بالإيميل", "detail_en": "The consulate says to book at least 6 weeks before your trip, and the trip must be at least 15 days after you hand in the application. With few weekly slots, up to 60 days for a decision and up to 30 days for superlegalization, we suggest starting about 4 months ahead.", "detail_ar": "تقول القنصلية أن تحجز قبل رحلتك بـ6 أسابيع على الأقل، وأن تكون الرحلة بعد تقديم الطلب بـ15 يومًا على الأقل. ومع قلة المواعيد الأسبوعية، وحتى 60 يومًا للقرار و30 يومًا للتصديق، نقترح أن تبدأ قبل نحو 4 أشهر.", "copies": null, "anchor": "departure", "lead_days": 120, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://mzv.gov.cz/erbil/en/visa_and_consular_information/visa_section/registration_of_visa_appointment/index.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "visa_application_form", "title_en": "Visa application form", "title_ar": "استمارة طلب التأشيرة", "detail_en": "Completed and signed. Fingerprints are taken when you apply, from age 12.", "detail_ar": "مملوءة وموقّعة. تؤخذ البصمات عند التقديم ابتداءً من سن 12.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "The original. Other Czech missions ask for at least 3 months of validity beyond the visa; not confirmed for Erbil.", "detail_ar": "الأصل. تطلب بعثات تشيكية أخرى صلاحية 3 أشهر على الأقل بعد انتهاء التأشيرة؛ غير مؤكد لأربيل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "acceptance_letter", "title_en": "University acceptance letter", "title_ar": "رسالة القبول من الجامعة", "detail_en": "The original, no older than 180 days, with an official Czech translation. Foreign public documents need an apostille or superlegalization.", "detail_ar": "الأصل، بما لا يزيد عمره على 180 يومًا، مع ترجمة رسمية إلى التشيكية. وتحتاج الوثائق الرسمية الأجنبية إلى أپوستيل أو تصديق قنصلي.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Proof of funds", "title_ar": "إثبات القدرة المالية", "detail_en": "Proof that covers your housing costs, or that a sponsor, stipend or grant pays all your costs, in Czech. The Tel Aviv mission asks for 15 times the subsistence minimum for the first month plus twice it for each further month (CZK 115,810 for a year); not confirmed for Erbil.", "detail_ar": "إثبات يغطي تكاليف سكنك، أو أن جهة كافلة أو راتبًا أو منحة تدفع كل تكاليفك، باللغة التشيكية. وتطلب بعثة تل أبيب 15 ضعف الحد الأدنى للمعيشة للشهر الأول وضعفيه لكل شهر بعده (115,810 كرونة تشيكية للسنة)؛ غير مؤكد لأربيل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "accommodation", "title_en": "Proof of accommodation", "title_ar": "إثبات السكن", "detail_en": "A dormitory confirmation or a lease, in Czech.", "detail_ar": "تأكيد من السكن الجامعي أو عقد إيجار، باللغة التشيكية.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "criminal_record", "title_en": "Criminal record certificate", "title_ar": "شهادة عدم المحكومية", "detail_en": "With an official Czech translation. It is verified first by the Iraqi Ministry of Foreign Affairs, then superlegalized at the consular section in Erbil (up to 30 days; fee in euros, amount not confirmed), and handed in with the application.", "detail_ar": "مع ترجمة رسمية إلى التشيكية. تُصدَّق أولًا من وزارة الخارجية العراقية، ثم تُصدَّق في القسم القنصلي في أربيل (حتى 30 يومًا؛ الرسم باليورو والمبلغ غير مؤكد)، وتُسلَّم مع الطلب.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/erbil/en/visa_and_consular_information/consular_section/legalisation_superlegalisation_of.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "photos_35x45", "title_en": "Two photos", "title_ar": "صورتان شخصيتان", "detail_en": "Showing how you look now. Other Czech missions ask for 35 x 45 mm, ICAO standard, on a plain light background.", "detail_ar": "تُظهر شكلك الحالي. تطلب بعثات تشيكية أخرى مقاس 35 × 45 ملم وفق معيار الإيكاو وبخلفية فاتحة سادة.", "copies": 2, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "parental_consent", "title_en": "Parental consent", "title_ar": "موافقة الوالدين", "detail_en": "The original, in free form, signed by both parents or guardians; it needs no official verification. Under 12 need no fingerprints or visit; ages 12 to 15 attend with the parents or guardians who lodge the application.", "detail_ar": "الأصل، بصيغة حرة، موقّعة من الوالدين أو الأوصياء كليهما، ولا تحتاج إلى تصديق رسمي. لا يحتاج من هم دون 12 إلى بصمات أو حضور، ويحضر من أعمارهم من 12 إلى 15 مع الوالدين أو الأوصياء الذين يقدّمون الطلب.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "travel_insurance", "title_en": "Travel medical insurance", "title_ar": "تأمين طبي للسفر", "detail_en": "Only after approval, when you collect the visa, with an officially verified Czech translation of the policy and its conditions. Other missions ask for at least EUR 400,000 per event, from an insurer authorized in Czechia, for the whole stay.", "detail_ar": "بعد الموافقة فقط، عند استلام التأشيرة، مع ترجمة تشيكية مصدّقة رسميًا للوثيقة وشروطها. وتطلب بعثات أخرى تغطية لا تقل عن 400,000 يورو لكل حالة، من شركة تأمين مرخّصة في التشيك، طوال مدة الإقامة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}, {"kind": "task", "doc_key": null, "title_en": "Prepare a set of copies", "title_ar": "جهّز نسخة من كل الوثائق", "detail_en": "Bring the originals of your passport, the acceptance letter and parental consent. Other papers may be originals or officially verified copies no older than 180 days.", "detail_ar": "أحضر أصل جواز السفر ورسالة القبول وموافقة الوالدين. ويمكن أن تكون الأوراق الأخرى أصولًا أو نسخًا مصدّقة رسميًا لا يزيد عمرها على 180 يومًا.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://mzv.gov.cz/jnp/en/information_for_aliens/long_stay_visa/study_long_term.html", "checked_on": "2026-11-04"}]},
{"slug": "hungary-stipendium-hungaricum", "country": "HU", "visa_ar": "تأشيرة من نوع «D» لاستلام الإقامة (منحة «Stipendium Hungaricum»)", "visa_en": "Type D visa to collect a residence permit (Stipendium Hungaricum)", "apply_at_ar": "القنصلية العامة لهنغاريا في أربيل، للإقامات الطويلة عدا لمّ الشمل. لا تتولى السفارة في بغداد أي شؤون قنصلية، ولا تتولى في إف إس غلوبال إلا الإقامات القصيرة. يحجز حاملو المنحة والمنح الأخرى بإرسال رسالة المنحة إلى consulate.erbil@mfa.gov.hu، ويستخدم الآخرون نظام الحجز الإلكتروني.", "apply_at_en": "Consulate General of Hungary in Erbil, for long stays other than family reunification. The Embassy in Baghdad handles no consular matters, and VFS Global handles only short stays. Stipendium Hungaricum and other scholarship holders book by emailing their Letter of Award to consulate.erbil@mfa.gov.hu; others use the online booking system.", "ask_ar": "القنصلية الهنغارية العامة في أربيل: consulate.erbil@mfa.gov.hu", "ask_en": "The Hungarian Consulate General in Erbil: consulate.erbil@mfa.gov.hu", "note_ar": "ثقة متوسطة: مسار أربيل من صفحات هنغاريا الرسمية، أما قائمة الوثائق فمن البعثة الهنغارية في القاهرة (دفعة 2026) وغير مؤكدة لأربيل. بعد الموافقة تحصل على تأشيرة دخول واحد لمدة 30 يومًا وتستلم بطاقة الإقامة من دائرة الهجرة خلالها. تقول بعثات أخرى إنها مجانية لحاملي المنحة، ومدة المعاملة في أربيل غير مؤكدة. اقبل عرضك في منصة دريم أبلاي أولًا، فرسائل القبول تصدر بعدها.", "note_en": "Medium confidence: the Erbil route is from Hungary's own pages; the document list comes from the Hungarian mission in Cairo (2026 intake) and is not confirmed for Erbil. After approval you get a single-entry 30-day visa and collect the residence card from the immigration authority within that time. Other missions say it is free for Stipendium Hungaricum holders; processing time for Erbil is not confirmed. Accept your offer in DreamApply first, since admission letters follow it.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "award_letter", "title_en": "Letter of Award from Tempus Public Foundation", "title_ar": "رسالة المنحة من مؤسسة تيمپوس العامة", "detail_en": "Needed to book in Erbil. Bring the original to the appointment (Cairo mission).", "detail_ar": "مطلوبة للحجز في أربيل. أحضر الأصل إلى الموعد (حسب بعثة القاهرة).", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://erbil.mfa.gov.hu/en/residence-permit-information", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "visa_application_form", "title_en": "Signed application form and Appendix 13", "title_ar": "استمارة الطلب موقّعة والملحق 13", "detail_en": "From the Cairo mission's list; not confirmed for Erbil.", "detail_ar": "من قائمة بعثة القاهرة؛ غير مؤكدة لأربيل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "acceptance_letter", "title_en": "Letter of admission from the university", "title_ar": "رسالة القبول من الجامعة", "detail_en": "From the Cairo mission's list; not confirmed for Erbil.", "detail_ar": "من قائمة بعثة القاهرة؛ غير مؤكدة لأربيل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "passport", "title_en": "Valid passport", "title_ar": "جواز سفر صالح", "detail_en": "Cairo recommends at least two years of validity; Baku asks for one.", "detail_ar": "توصي بعثة القاهرة بصلاحية سنتين على الأقل، وتطلب بعثة باكو سنة واحدة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "accommodation", "title_en": "Proof of accommodation", "title_ar": "إثبات السكن", "detail_en": "A dormitory listed on the admission letter, or a signed lease (Cairo).", "detail_ar": "سكن جامعي مذكور في رسالة القبول، أو عقد إيجار موقّع (حسب بعثة القاهرة).", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "diplomas_transcripts", "title_en": "Degrees and transcripts", "title_ar": "الشهادات وكشوف الدرجات", "detail_en": "High school and any degrees, in English; copies only with the originals (Cairo).", "detail_ar": "شهادة الإعدادية وأي شهادات أخرى، بالإنجليزية؛ والنسخ مقبولة مع الأصول فقط (حسب بعثة القاهرة).", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "language_proof", "title_en": "Proof of the language of study", "title_ar": "إثبات لغة الدراسة", "detail_en": "A language exam result, or a diploma showing the language of instruction (Cairo).", "detail_ar": "نتيجة امتحان لغة، أو شهادة تبيّن لغة التدريس (حسب بعثة القاهرة).", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Bank statement", "title_ar": "كشف حساب مصرفي", "detail_en": "A certified statement for the last 6 months, yours or a parent's or guardian's, with a commitment letter, a copy of the sponsor's ID and proof of family ties such as a birth certificate, in English (Cairo).", "detail_ar": "كشف مصدّق لآخر 6 أشهر، باسمك أو باسم أحد الوالدين أو الوصي، مع رسالة تعهد ونسخة من هوية الكفيل وإثبات صلة القرابة مثل شهادة الميلاد، بالإنجليزية (حسب بعثة القاهرة).", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "photos_35x45", "title_en": "One passport photo", "title_ar": "صورة شخصية واحدة", "detail_en": "3.5 x 4.5 cm, white background, taken within 3 months (Cairo).", "detail_ar": "مقاس 3.5 × 4.5 سم، بخلفية بيضاء، ملتقطة خلال آخر 3 أشهر (حسب بعثة القاهرة).", "copies": 1, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "Who must attend for an applicant under 18", "title_ar": "من يجب أن يحضر مع المتقدم دون 18", "detail_en": "Missions differ: Cairo asks for both parents with notarized consent from both; Baku for at least one parent with consent and a power of attorney. Ask Erbil.", "detail_ar": "تختلف البعثات: تطلب القاهرة حضور الوالدين كليهما مع موافقة مصدّقة من كليهما، وتطلب باكو حضور أحد الوالدين على الأقل مع موافقة ووكالة. اسأل قنصلية أربيل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "unconfirmed", "source_url": "https://cairo.mfa.gov.hu/en/articles/visa-process-2026-stipendium-hungaricum-scholarship-holders", "checked_on": "2026-11-04"}]},
{"slug": "germany-national-study", "country": "DE", "visa_ar": "تأشيرة وطنية للدراسة أو لدورة لغة", "visa_en": "National visa for study or a language course", "apply_at_ar": "القنصلية الألمانية العامة في أربيل. احجز من بوابة في إف إس غلوبال لألمانيا والعراق: أنشئ حسابًا، واختر ألمانيا وإقليم كردستان العراق، ثم القنصلية العامة في أربيل، وأضف بيانات المتقدم واختر موعدًا (التواريخ الخضراء متاحة والبيضاء ممتلئة). الدفع في المصرف متاح في إقليم كردستان فقط، ومن خارج العراق ادفع بالبطاقة إلكترونيًا. لم يتأكد هل تتولى بغداد تأشيرات الدراسة.", "apply_at_en": "German Consulate General in Erbil. Book on the VFS Global Germany–Iraq portal: create an account, choose Germany and Iraq-KRG/Syria, then the Consulate General Erbil, add the applicant and pick a date (green dates are free, white are full). Paying at a bank works only in the Kurdistan Region; pay online by card from outside Iraq. Whether Baghdad handles student visas was not confirmed.", "ask_ar": "القنصلية الألمانية العامة في أربيل، عبر بوابة في إف إس غلوبال.", "ask_en": "The German Consulate General in Erbil, through the VFS Global portal.", "note_ar": "ثقة متوسطة إلى منخفضة: مسار الحجز من دليل في إف إس غلوبال للعراق، أما قائمة الوثائق فمن السفارة الألمانية في المنامة (نيسان 2024) وغير مؤكدة لأربيل. هناك كان الرسم 75 يورو (ورسوم في إف إس إضافية) والمعاملة حتى 12 أسبوعًا. يتغير المبلغ المطلوب إثباته كل سنة ولم يتأكد من صفحة رسمية. لا تشترِ تذكرة الطيران قبل منح التأشيرة.", "note_en": "Medium-low confidence: the booking route is from VFS Global's guide for Iraq; the document list comes from the German Embassy in Manama (April 2024) and is not confirmed for Erbil. There the fee was EUR 75 (VFS charges extra) and processing up to 12 weeks. The amount to show changes every year and was not confirmed from an official page. Don't buy a flight until the visa is granted.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Its number and expiry are entered when you book. The full national visa list for Iraq was not read.", "detail_ar": "يُدخل رقمه وتاريخ انتهائه عند الحجز. لم تُقرأ القائمة الكاملة للتأشيرة الوطنية للعراق.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.vfsglobal.com/germany/iraq/pdf/National-visa-appointment-latest-12.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Proof of financial means", "title_ar": "إثبات القدرة المالية", "detail_en": "A blocked account opened before applying, a formal obligation letter from a resident of Germany, or proof of a German scholarship. Officially translated unless in English or German.", "detail_ar": "حساب مجمّد يُفتح قبل التقديم، أو تعهد رسمي من مقيم في ألمانيا، أو إثبات منحة ألمانية. مترجم ترجمة رسمية ما لم يكن بالإنجليزية أو الألمانية.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://manama.diplo.de/blob/2632292/db4fa1187bf3f702aadd1f9f960866a0/download-checklist-study-data.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "health_insurance", "title_en": "Health insurance", "title_ar": "تأمين صحي", "detail_en": "Private cover until statutory insurance starts when you enrol. Officially translated unless in English or German.", "detail_ar": "تغطية خاصة حتى يبدأ التأمين القانوني عند التسجيل. مترجم ترجمة رسمية ما لم يكن بالإنجليزية أو الألمانية.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://manama.diplo.de/blob/2632292/db4fa1187bf3f702aadd1f9f960866a0/download-checklist-study-data.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "photos_35x45", "title_en": "Two biometric photos", "title_ar": "صورتان بيومتريتان", "detail_en": "35 x 45 mm, no older than 6 months, not digitally processed.", "detail_ar": "مقاس 35 × 45 ملم، لا يزيد عمرها على 6 أشهر، دون معالجة رقمية.", "copies": 2, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://manama.diplo.de/blob/2632292/db4fa1187bf3f702aadd1f9f960866a0/download-checklist-study-data.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "parental_consent", "title_en": "Birth certificate, parents' authorization and IDs", "title_ar": "شهادة الميلاد وتفويض الوالدين وهويتاهما", "detail_en": "The authorization is signed by both parents, who generally both attend; officially translated unless in English or German. Fingerprints are taken from age 12.", "detail_ar": "يوقّع الوالدان كلاهما التفويض ويحضران عادةً، مع ترجمة رسمية ما لم تكن الوثائق بالإنجليزية أو الألمانية. تؤخذ البصمات من سن 12.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "unconfirmed", "source_url": "https://manama.diplo.de/blob/2632292/db4fa1187bf3f702aadd1f9f960866a0/download-checklist-study-data.pdf", "checked_on": "2026-11-04"}]},
{"slug": "uk-student", "country": "GB", "visa_ar": "تأشيرة طالب", "visa_en": "Student visa", "apply_at_ar": "قدّم إلكترونيًا على موقع الحكومة البريطانية، ثم راجع مركز تأشيرات في إف إس غلوبال؛ يذكر الموقع مركزًا للعراق. لم تُقرأ أسماء المدن.", "apply_at_en": "Apply online on GOV.UK, then go to a VFS Global visa application centre; GOV.UK lists one for Iraq. The cities were not read.", "ask_ar": "مكتب الطلبة الدوليين في جامعتك، وصفحات تأشيرة الطالب على موقع الحكومة البريطانية.", "ask_en": "Your course provider's international office, and the GOV.UK student visa pages.", "note_ar": "ثقة عالية في المبالغ والرسوم وفحص السل والتوقيت، ومتوسطة في الوثائق ومركز التأشيرات في العراق. قدّم قبل بدء الدراسة بـ6 أشهر كحد أقصى، ويصدر القرار عادةً خلال نحو 3 أسابيع من خارج المملكة المتحدة. يجب أن يكون عمرك 16 سنة أو أكثر (ولمن هم أصغر تأشيرة الطالب الطفل).", "note_en": "High confidence for money, fees, the TB test and timing; medium for documents and the visa centre in Iraq. Apply up to 6 months before the course; a decision usually takes about 3 weeks from outside the UK. You must be 16 or over (younger students use the Child Student visa).", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Current passport", "title_ar": "جواز سفر ساري", "detail_en": "Required.", "detail_ar": "مطلوب.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents-you-must-provide", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "cas", "title_en": "Confirmation of Acceptance for Studies (CAS)", "title_ar": "تأكيد القبول للدراسة («CAS»)", "detail_en": "From your course provider.", "detail_ar": "من الجهة التي تقدّم الدراسة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents-you-must-provide", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Proof of funds", "title_ar": "إثبات القدرة المالية", "detail_en": "Your course fees on the CAS plus up to 9 months of living costs: GBP 1,529 a month in London, GBP 1,171 elsewhere. Held for 28 days in a row, ending within 31 days of applying. Whether Iraqis are exempt was not confirmed.", "detail_ar": "رسوم الدراسة المذكورة في «CAS» مع تكاليف معيشة لـ9 أشهر كحد أقصى: 1,529 جنيهًا إسترلينيًا شهريًا في لندن و1,171 في غيرها. تبقى في الحساب 28 يومًا متتالية تنتهي خلال 31 يومًا من التقديم. لم يتأكد هل العراقيون معفون.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/money", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "tb_test", "title_en": "TB test certificate", "title_ar": "شهادة فحص السل", "detail_en": "Iraq is on the list: needed if you are coming for 6 months or more. From an approved clinic (IOM: USD 150 from age 11, USD 70 under 11). Valid 6 months from the x-ray.", "detail_ar": "العراق مدرج في القائمة: مطلوبة إذا كانت إقامتك 6 أشهر أو أكثر. من عيادة معتمدة (المنظمة الدولية للهجرة: 150 دولارًا من سن 11، و70 دولارًا دونها). صالحة 6 أشهر من تاريخ الأشعة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/tb-test-visa", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "english_proof", "title_en": "Evidence of your English", "title_ar": "إثبات مستوى الإنجليزية", "detail_en": "Required; which evidence is accepted was not read.", "detail_ar": "مطلوب، ولم يُقرأ نوع الإثبات المقبول.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "atas", "title_en": "ATAS certificate", "title_ar": "شهادة «ATAS»", "detail_en": "Only if your course and nationality require it.", "detail_ar": "فقط إذا تطلبتها دراستك وجنسيتك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents-you-must-provide", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "sponsor_consent", "title_en": "Sponsor's written consent", "title_ar": "موافقة مكتوبة من الجهة الكافلة", "detail_en": "If a financial sponsor paid your fees or living costs in the last 12 months.", "detail_ar": "إذا دفعت جهة كافلة رسومك أو تكاليف معيشتك خلال آخر 12 شهرًا.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents-you-must-provide", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "parental_consent", "title_en": "Parental consent and proof of relationship", "title_ar": "موافقة الوالدين وإثبات القرابة", "detail_en": "For 16 and 17: written consent from both parents or guardians, or one with sole responsibility, for the application, living and care in the UK, and travel; with a birth certificate or another document showing your parents' names.", "detail_ar": "لمن عمره 16 أو 17: موافقة مكتوبة من الوالدين أو الأوصياء كليهما، أو من أحدهما إذا كانت له المسؤولية وحده، على الطلب والسكن والرعاية في المملكة المتحدة والسفر؛ مع شهادة ميلاد أو وثيقة أخرى فيها اسما الوالدين.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "official", "source_url": "https://www.gov.uk/student-visa/documents-you-must-provide", "checked_on": "2026-11-04"}, {"kind": "task", "doc_key": null, "title_en": "Pay the visa fee and the health surcharge", "title_ar": "ادفع رسم التأشيرة ورسم الرعاية الصحية", "detail_en": "GBP 558 from outside the UK, plus the Immigration Health Surcharge of GBP 776 for each year.", "detail_ar": "558 جنيهًا إسترلينيًا من خارج المملكة المتحدة، مع رسم الرعاية الصحية 776 جنيهًا لكل سنة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/healthcare-immigration-application/how-much-pay", "checked_on": "2026-11-04"}]},
{"slug": "uk-standard-visitor", "country": "GB", "visa_ar": "زائر عادي (زيارة قصيرة، أو دراسة حتى 6 أشهر)", "visa_en": "Standard Visitor (a short visit, or study up to 6 months)", "apply_at_ar": "قدّم إلكترونيًا على موقع الحكومة البريطانية، ثم راجع مركز تأشيرات في إف إس غلوبال؛ يذكر الموقع مركزًا للعراق.", "apply_at_en": "Apply online on GOV.UK, then go to a VFS Global visa application centre; GOV.UK lists one for Iraq.", "ask_ar": "صفحات الزائر العادي على موقع الحكومة البريطانية.", "ask_en": "The GOV.UK Standard Visitor pages.", "note_ar": "ثقة متوسطة. لم يتأكد من جدول الموقع البريطاني هل يحتاج العراقيون إلى تأشيرة أو إذن سفر إلكتروني؛ تحقق قبل التقديم. الرسم 135 جنيهًا إسترلينيًا لمدة حتى 6 أشهر. لا تقدّم قبل السفر بأكثر من 3 أشهر. ولا يلزم فحص السل عادةً لإقامة أقل من 6 أشهر.", "note_en": "Medium confidence. Whether Iraqis need a visa or an ETA was not confirmed from GOV.UK's table; check before applying. GBP 135 for up to 6 months. Apply no earlier than 3 months before you travel. A TB test is generally not needed for stays under 6 months.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Valid for your whole stay.", "detail_ar": "صالح طوال مدة إقامتك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/standard-visitor", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Evidence you will leave and can pay", "title_ar": "إثبات أنك ستغادر وتستطيع الإنفاق", "detail_en": "That you will leave at the end of the visit, can support yourself and any dependants, and can pay for your return. Which documents prove it was not read.", "detail_ar": "أنك ستغادر في نهاية الزيارة، وتستطيع إعالة نفسك ومن معك، ودفع تكاليف عودتك. لم تُقرأ الوثائق التي تثبت ذلك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.gov.uk/standard-visitor", "checked_on": "2026-11-04"}, {"kind": "question", "doc_key": null, "title_en": "Rules for travellers under 18", "title_ar": "قواعد المسافرين دون 18", "detail_en": "GOV.UK has a section for under-18s that was not read.", "detail_ar": "في موقع الحكومة البريطانية قسم لمن هم دون 18 لم يُقرأ.", "copies": null, "anchor": null, "lead_days": null, "minors_only": true, "confidence": "unconfirmed", "source_url": "https://www.gov.uk/standard-visitor", "checked_on": "2026-11-04"}]},
{"slug": "us-j1-exchange", "country": "US", "visa_ar": "تأشيرة الزائر في برنامج تبادل («J-1»)", "visa_en": "J-1 Exchange Visitor visa", "apply_at_ar": "لا تتوفر معالجة التأشيرات الاعتيادية في العراق (السفارة الأمريكية، تشرين الأول 2026)، مع أن السفارة في بغداد والقنصلية في أربيل مفتوحتان. قدّم في بلد إقامتك أو جنسيتك؛ ولم نجد مقرًا رسميًا مخصصًا للعراقيين في بلد آخر، والتقديم خارجهما قد يكون أصعب ويتطلب إثبات إقامتك هناك. املأ استمارة «DS-160» إلكترونيًا، ثم احجز المقابلة في المقر الذي تختاره برقم الطلب.", "apply_at_en": "Routine visa processing is not available in Iraq (US Embassy, October 2026), although the embassy in Baghdad and the consulate in Erbil are open. Apply in your country of residence or nationality; no official post for Iraqis elsewhere was found, and applying outside them may be harder and needs proof that you live there. Complete the DS-160 online, then schedule the interview at your chosen post with its application number.", "ask_ar": "الجهة الراعية لبرنامجك أو جامعتك، وصفحات التأشيرات في موقع السفارة الأمريكية في العراق.", "ask_en": "Your program sponsor or school, and the US Embassy in Iraq's visa pages.", "note_ar": "ثقة عالية بأن المعالجة الاعتيادية غير متوفرة في العراق، ومنخفضة بشأن المكان الذي يمكن للعراقي التقديم فيه. رسم الطلب 185 دولارًا (ولا رسم لبرامج الحكومة الأمريكية ذات الأرقام «G-1» و«G-2» و«G-3» و«G-7»)، ورسم «SEVIS» منفصل. المقابلة للأعمار من 14 إلى 79. تنتهي أغلب المعالجات الإدارية خلال 60 يومًا وقد تستغرق سنة. لا دخول قبل بدء البرنامج بأكثر من 30 يومًا، ولا تشترِ التذاكر قبل التأشيرة. قد تنطبق قاعدة السنتين في البلد الأم على البرامج الممولة حكوميًا. وعلى المتقدمين لتأشيرتي «F» و«J» جعل حساباتهم على مواقع التواصل عامة.", "note_en": "High confidence that routine processing is unavailable in Iraq; low on where an Iraqi can apply. Application fee USD 185 (none for US government-sponsored programs with G-1, G-2, G-3 or G-7 numbers); the SEVIS fee is separate. Interviews for ages 14 to 79. Most administrative processing ends within 60 days but can take a year. No entry more than 30 days before the program; don't buy tickets before the visa. A two-year home-country rule may apply to government-funded programs. F and J applicants must make their social media accounts public.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Generally valid at least six months beyond your stay. Only A, C, D and E series Iraqi passports are accepted for US visas.", "detail_ar": "صالح عادةً لستة أشهر على الأقل بعد انتهاء إقامتك. تُقبل للتأشيرات الأمريكية جوازات السفر العراقية من السلاسل «A» و«C» و«D» و«E» فقط.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/Visa-Reciprocity-and-Civil-Documents-by-Country/Iraq.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "ds160", "title_en": "DS-160 confirmation page", "title_ar": "صفحة تأكيد «DS-160»", "detail_en": "Required.", "detail_ar": "مطلوبة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "ds2019", "title_en": "Form DS-2019", "title_ar": "استمارة «DS-2019»", "detail_en": "From your program sponsor.", "detail_ar": "من الجهة الراعية لبرنامجك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "ds7002", "title_en": "Form DS-7002", "title_ar": "استمارة «DS-7002»", "detail_en": "Trainee and intern categories only.", "detail_ar": "لفئتي المتدربين والمتدربين الداخليين فقط.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "us_visa_photo", "title_en": "Visa photo", "title_ar": "صورة التأشيرة", "detail_en": "Uploaded in the DS-160 and meeting the State Department's rules; the specifications were not read.", "detail_ar": "تُرفع في استمارة «DS-160» ويجب أن تطابق شروط وزارة الخارجية الأمريكية؛ لم تُقرأ المواصفات.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "visa_fee_receipt", "title_en": "Application fee receipt", "title_ar": "وصل دفع رسم الطلب", "detail_en": "If payment is required before the interview.", "detail_ar": "إذا كان الدفع مطلوبًا قبل المقابلة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "sevis_fee", "title_en": "SEVIS fee receipt", "title_ar": "وصل دفع رسم «SEVIS»", "detail_en": "Most J-1 applicants pay before the visa is issued. Confirm the amount on the official I-901 payment site.", "detail_ar": "يدفعه أغلب متقدمي «J-1» قبل إصدار التأشيرة. تأكد من المبلغ في موقع الدفع الرسمي «I-901».", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://iq.usembassy.gov/study-exchanges-how-to-apply/", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "us_supporting_evidence", "title_en": "Evidence of your plans, ties and funds", "title_ar": "إثباتات خططك وارتباطك وقدرتك المالية", "detail_en": "The officer may ask how your costs are paid and why you will return; there is no fixed list. The embassy advises against unnecessary translations.", "detail_ar": "قد يسألك الموظف كيف تُدفع تكاليفك ولماذا ستعود؛ لا توجد قائمة ثابتة. وتنصح السفارة بتجنب الترجمات غير الضرورية.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://iq.usembassy.gov/study-exchanges-how-to-apply/", "checked_on": "2026-11-04"}]},
{"slug": "us-f1-student", "country": "US", "visa_ar": "تأشيرة الطالب («F-1»)", "visa_en": "F-1 Student visa", "apply_at_ar": "لا تتوفر معالجة التأشيرات الاعتيادية في العراق (السفارة الأمريكية، تشرين الأول 2026)، مع أن السفارة في بغداد والقنصلية في أربيل مفتوحتان. قدّم في بلد إقامتك أو جنسيتك؛ ولم نجد مقرًا رسميًا مخصصًا للعراقيين في بلد آخر، والتقديم خارجهما قد يكون أصعب ويتطلب إثبات إقامتك هناك. املأ استمارة «DS-160» إلكترونيًا، ثم احجز المقابلة في المقر الذي تختاره برقم الطلب.", "apply_at_en": "Routine visa processing is not available in Iraq (US Embassy, October 2026), although the embassy in Baghdad and the consulate in Erbil are open. Apply in your country of residence or nationality; no official post for Iraqis elsewhere was found, and applying outside them may be harder and needs proof that you live there. Complete the DS-160 online, then schedule the interview at your chosen post with its application number.", "ask_ar": "الجهة الراعية لبرنامجك أو جامعتك، وصفحات التأشيرات في موقع السفارة الأمريكية في العراق.", "ask_en": "Your program sponsor or school, and the US Embassy in Iraq's visa pages.", "note_ar": "ثقة عالية بأن المعالجة الاعتيادية غير متوفرة في العراق، ومنخفضة بشأن المكان الذي يمكن للعراقي التقديم فيه. رسم الطلب 185 دولارًا، ورسم «SEVIS» منفصل. المقابلة للأعمار من 14 إلى 79. تنتهي أغلب المعالجات الإدارية خلال 60 يومًا وقد تستغرق سنة. قد تصدر التأشيرة قبل بدء دراستك بما يصل إلى 365 يومًا، لكن لا يجوز الدخول قبلها بأكثر من 30 يومًا. وعلى المتقدمين لتأشيرتي «F» و«J» جعل حساباتهم على مواقع التواصل عامة.", "note_en": "High confidence that routine processing is unavailable in Iraq; low on where an Iraqi can apply. Application fee USD 185; the SEVIS fee is separate. Interviews for ages 14 to 79. Most administrative processing ends within 60 days but can take a year. The visa may be issued up to 365 days before your program starts, but you may not enter more than 30 days before it. F and J applicants must make their social media accounts public.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Passport", "title_ar": "جواز السفر", "detail_en": "Generally valid at least six months beyond your stay. Only A, C, D and E series Iraqi passports are accepted for US visas.", "detail_ar": "صالح عادةً لستة أشهر على الأقل بعد انتهاء إقامتك. تُقبل للتأشيرات الأمريكية جوازات السفر العراقية من السلاسل «A» و«C» و«D» و«E» فقط.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/Visa-Reciprocity-and-Civil-Documents-by-Country/Iraq.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "i20", "title_en": "Form I-20", "title_ar": "استمارة «I-20»", "detail_en": "From your school, shown at the interview.", "detail_ar": "من جامعتك، وتُعرض في المقابلة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/student-visa.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "sevis_fee", "title_en": "SEVIS I-901 fee receipt", "title_ar": "وصل دفع رسم «SEVIS I-901»", "detail_en": "Paid after the school accepts you.", "detail_ar": "يُدفع بعد قبولك في الجامعة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/student-visa.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "ds160", "title_en": "DS-160 confirmation page", "title_ar": "صفحة تأكيد «DS-160»", "detail_en": "Required.", "detail_ar": "مطلوبة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "us_visa_photo", "title_en": "Visa photo", "title_ar": "صورة التأشيرة", "detail_en": "Uploaded in the DS-160 and meeting the State Department's rules; the specifications were not read.", "detail_ar": "تُرفع في استمارة «DS-160» ويجب أن تطابق شروط وزارة الخارجية الأمريكية؛ لم تُقرأ المواصفات.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://travel.state.gov/content/travel/en/us-visas/study/exchange.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "us_supporting_evidence", "title_en": "Evidence of your plans, ties and funds", "title_ar": "إثباتات خططك وارتباطك وقدرتك المالية", "detail_en": "The officer may ask how your costs are paid and why you will return; there is no fixed list. The embassy advises against unnecessary translations.", "detail_ar": "قد يسألك الموظف كيف تُدفع تكاليفك ولماذا ستعود؛ لا توجد قائمة ثابتة. وتنصح السفارة بتجنب الترجمات غير الضرورية.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://iq.usembassy.gov/study-exchanges-how-to-apply/", "checked_on": "2026-11-04"}]},
{"slug": "japan-short-stay", "country": "JP", "visa_ar": "تأشيرة إقامة قصيرة (حتى 90 يومًا)", "visa_en": "Short-term stay visa (up to 90 days)", "apply_at_ar": "عبر وكالة سفر معتمدة تغطي مكان سكنك: هناك قائمتان، واحدة للعراق خارج إقليم كردستان (الحياة ومون لاين وطريق الأفق، ولها مكاتب في بغداد والبصرة والنجف) وأخرى لإقليم كردستان. ويمكن أن ينوب عنك شخص بوكالة. ولا يقدّم مباشرةً في السفارة في بغداد أو المكتب القنصلي في أربيل إلا للرحلات الرسمية، والدعوات من حكومة اليابان أو جهات مثل جايكا ومؤسسة اليابان وجيترو، وطلبة منحة الحكومة اليابانية، والحالات الإنسانية العاجلة.", "apply_at_en": "Through an accredited travel agency that covers where you live: there are separate lists for Iraq outside the Kurdistan Region (Al-Hayat, Moonline and Tareek Alofuk, with offices in Baghdad, Basra and Najaf) and for the Kurdistan Region. Someone else may go for you with a power of attorney. Only official trips, invitations from Japan's government or bodies such as JICA, the Japan Foundation or JETRO, MEXT scholars and urgent humanitarian cases apply directly at the Embassy in Baghdad or the Consular Office in Erbil.", "ask_ar": "سفارة اليابان في العراق.", "ask_en": "The Embassy of Japan in Iraq.", "note_ar": "ثقة عالية في المسار والرسم ومدة المعاملة، ومتوسطة في الوثائق. الرسم 136,000 دينار عراقي للشخص ابتداءً من 1 تموز 2026، يُدفع نقدًا للوكالة، ولا رسم إذا رُفضت التأشيرة؛ وقد تضيف الوكالات أجورها. نحو 5 أيام عمل إذا كان ملفك كاملًا، وحتى شهرين إذا أُحيل إلى اليابان. ولا تذكر الصفحات المقروءة شيئًا عن القاصرين.", "note_en": "High confidence for the route, fee and processing; medium for documents. Fee 136,000 IQD per person from 1 July 2026, paid in cash to the agency, with no fee if the visa is refused; agencies may add their own charge. About 5 working days if your file is complete, up to 2 months if it is referred to Japan. The pages read say nothing about minors.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Valid passport", "title_ar": "جواز سفر صالح", "detail_en": "With at least 2 blank visa pages, valid for your stay.", "detail_ar": "فيه صفحتان فارغتان للتأشيرة على الأقل، وصالح طوال إقامتك.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.iraq.emb-japan.go.jp/itpr_en/visitingjapan.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "visa_application_form", "title_en": "Visa application form and one photo", "title_ar": "استمارة طلب التأشيرة وصورة واحدة", "detail_en": "The form is on the embassy's page; the photo size is not given.", "detail_ar": "الاستمارة في صفحة السفارة، ومقاس الصورة غير مذكور.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.iraq.emb-japan.go.jp/itpr_en/visitingjapan.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "itinerary", "title_en": "Schedule of stay", "title_ar": "برنامج الإقامة", "detail_en": "Your itinerary, with flights and dates.", "detail_ar": "خط رحلتك مع الرحلات الجوية والتواريخ.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mofa.go.jp/files/000121327.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "proof_of_funds", "title_en": "Proof of your purpose and that you can pay", "title_ar": "إثبات الغرض والقدرة على الدفع", "detail_en": "A business letter or proof of relationship as relevant. If you pay yourself: an income certificate, a tax return, or a bank statement or balance certificate. No amount is given.", "detail_ar": "رسالة عمل أو إثبات قرابة حسب الحالة. وإذا كنت تدفع بنفسك: شهادة دخل أو إقرار ضريبي أو كشف حساب أو شهادة رصيد. لا يُذكر مبلغ محدد.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mofa.go.jp/files/000121327.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "invitation_letter", "title_en": "Letter of invitation and the inviter's documents", "title_ar": "رسالة الدعوة ووثائق الداعي", "detail_en": "Addressed to the ambassador or consul general, listing specific activities (\"tourism\" alone is not accepted), issued within 3 months.", "detail_ar": "موجهة إلى السفير أو القنصل العام، وتذكر أنشطة محددة (لا تكفي كلمة «سياحة»)، وصادرة خلال 3 أشهر.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mofa.go.jp/files/000121327.pdf", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "guarantee_letter", "title_en": "Letter of guarantee", "title_ar": "رسالة الكفالة", "detail_en": "If a guarantor pays: with the guarantor's income or balance proof and residence certificate.", "detail_ar": "إذا دفع كفيل: مع إثبات دخله أو رصيده وشهادة إقامته.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mofa.go.jp/files/000121327.pdf", "checked_on": "2026-11-04"}]},
{"slug": "japan-student", "country": "JP", "visa_ar": "تأشيرة دراسة (إقامة طويلة)", "visa_en": "Student visa (long-term stay)", "apply_at_ar": "عبر وكالة سفر معتمدة. ويقدّم حاملو منحة الحكومة اليابانية مباشرةً في السفارة في بغداد أو المكتب القنصلي في أربيل. وقبل ذلك يستخرج لك شخص في اليابان (جامعتك عادةً) شهادة الأهلية من دائرة الهجرة الإقليمية.", "apply_at_en": "Through an accredited travel agency. Japanese Government (MEXT) scholarship holders apply directly at the Embassy in Baghdad or the Consular Office in Erbil. First, someone in Japan (usually your school) gets your Certificate of Eligibility from the regional immigration authority.", "ask_ar": "جامعتك في اليابان، وسفارة اليابان في العراق.", "ask_en": "Your school in Japan, and the Embassy of Japan in Iraq.", "note_ar": "ثقة متوسطة. الرسم 136,000 دينار عراقي للشخص ابتداءً من 1 تموز 2026، يُدفع نقدًا للوكالة، ولا رسم إذا رُفضت التأشيرة؛ وقد تضيف الوكالات أجورها. وقد يختلف الرسم حسب نوع التأشيرة. نحو 5 أيام عمل إذا كان ملفك كاملًا، وحتى شهرين إذا أُحيل؛ ومن دون شهادة الأهلية قد تستغرق عدة أشهر.", "note_en": "Medium confidence. Fee 136,000 IQD per person from 1 July 2026, paid in cash to the agency, with no fee if the visa is refused; agencies may add their own charge. The fee may differ by visa type. About 5 working days if your file is complete, up to 2 months if referred; without a Certificate of Eligibility it can take several months.", "checked_on": "2026-11-04", "lines": [{"kind": "document", "doc_key": "passport", "title_en": "Valid passport", "title_ar": "جواز سفر صالح", "detail_en": "With at least 2 blank visa pages.", "detail_ar": "فيه صفحتان فارغتان للتأشيرة على الأقل.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.iraq.emb-japan.go.jp/itpr_en/visitingjapan.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "visa_application_form", "title_en": "Visa application form and one passport photo", "title_ar": "استمارة طلب التأشيرة وصورة شخصية واحدة", "detail_en": "Required.", "detail_ar": "مطلوبة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.iraq.emb-japan.go.jp/itpr_en/visitingjapan.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "certificate_of_eligibility", "title_en": "Certificate of Eligibility", "title_ar": "شهادة الأهلية", "detail_en": "The original and a copy (the embassy); the foreign ministry also accepts one copy or a printed electronic certificate. It does not guarantee a visa.", "detail_ar": "الأصل ونسخة (حسب السفارة)؛ وتقبل وزارة الخارجية أيضًا نسخة واحدة أو شهادة إلكترونية مطبوعة. ولا تضمن الحصول على التأشيرة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.mofa.go.jp/j_info/visit/visa/long/visa6.html", "checked_on": "2026-11-04"}, {"kind": "document", "doc_key": "national_id", "title_en": "Iraqi ID", "title_ar": "هوية عراقية", "detail_en": "Required on the embassy's long-term list.", "detail_ar": "مطلوبة في قائمة السفارة للإقامة الطويلة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "official", "source_url": "https://www.iraq.emb-japan.go.jp/itpr_en/visitingjapan.html", "checked_on": "2026-11-04"}]},
{"slug": "malaysia-not-confirmed", "country": "MY", "visa_ar": "غير مؤكد (زيارة قصيرة أو تصريح دراسة)", "visa_en": "Not confirmed (short visit or student pass)", "apply_at_ar": "سفارة ماليزيا في بغداد. لم يتأكد طريق التقديم.", "apply_at_en": "Embassy of Malaysia in Baghdad. How to apply was not confirmed.", "ask_ar": "سفارة ماليزيا في بغداد، أو دائرة الهجرة الماليزية.", "ask_en": "The Embassy of Malaysia in Baghdad, or Malaysia's Immigration Department.", "note_ar": "ثقة منخفضة: تعذرت قراءة صفحة التأشيرات في السفارة. يقول موقع غير رسمي إنه لا تلزم تأشيرة لمدة تصل إلى 30 يومًا للسياحة واجتماعات العمل والعبور، لكن ليس للدراسة؛ وهو يناقض نفسه في مواضع أخرى، فلا تعتمد عليه.", "note_en": "Low confidence: the embassy's visa page could not be read. One unofficial site says no visa is needed for up to 30 days for tourism, business meetings and transit, but not for study; it contradicts itself elsewhere, so don't rely on it.", "checked_on": "2026-11-04", "lines": [{"kind": "question", "doc_key": null, "title_en": "Is a visa needed for your trip", "title_ar": "هل تحتاج رحلتك إلى تأشيرة", "detail_en": "Ask the embassy before you plan, for a short visit or for study.", "detail_ar": "اسأل السفارة قبل أن تخطط، للزيارة القصيرة أو للدراسة.", "copies": null, "anchor": null, "lead_days": null, "minors_only": false, "confidence": "unconfirmed", "source_url": "https://www.kln.gov.my/web/irq_baghdad/honorary_consul", "checked_on": "2026-11-04"}]}
]$json$::jsonb)
  loop
    select * into found_row
    from public.travel_routes r
    where r.slug = item ->> 'slug'
    for update;

    if found then
      if found_row.status <> 'draft'
        or found_row.updated_at <> found_row.created_at
        or exists (
          select 1 from public.travel_requirements q
          where q.route_id = found_row.id
            and (q.created_at <> found_row.created_at or q.updated_at <> q.created_at)
        )
      then
        kept := kept + 1;
        continue;
      end if;

      delete from public.travel_requirements q where q.route_id = found_row.id;
      update public.travel_routes r set
        country = item ->> 'country',
        visa_ar = item ->> 'visa_ar',
        visa_en = item ->> 'visa_en',
        apply_at_ar = item ->> 'apply_at_ar',
        apply_at_en = item ->> 'apply_at_en',
        ask_ar = item ->> 'ask_ar',
        ask_en = item ->> 'ask_en',
        note_ar = item ->> 'note_ar',
        note_en = item ->> 'note_en',
        checked_on = (item ->> 'checked_on')::date,
        created_at = now()
      where r.id = found_row.id;
      route := found_row.id;
      updated := updated + 1;
    else
      insert into public.travel_routes (
        slug, country, visa_ar, visa_en, apply_at_ar, apply_at_en, ask_ar, ask_en,
        note_ar, note_en, status, checked_on
      ) values (
        item ->> 'slug', item ->> 'country', item ->> 'visa_ar', item ->> 'visa_en',
        item ->> 'apply_at_ar', item ->> 'apply_at_en', item ->> 'ask_ar', item ->> 'ask_en',
        item ->> 'note_ar', item ->> 'note_en', 'draft', (item ->> 'checked_on')::date
      )
      returning id into route;
      added := added + 1;
    end if;

    pos := 0;
    for entry in select value from jsonb_array_elements(item -> 'lines')
    loop
      insert into public.travel_requirements (
        route_id, kind, doc_key, position, title_ar, title_en, detail_ar, detail_en,
        copies, anchor, lead_days, minors_only, confidence, source_url, checked_on
      ) values (
        route,
        (entry ->> 'kind')::public.travel_item_kind,
        entry ->> 'doc_key',
        pos,
        entry ->> 'title_ar', entry ->> 'title_en',
        entry ->> 'detail_ar', entry ->> 'detail_en',
        (entry ->> 'copies')::smallint,
        entry ->> 'anchor',
        (entry ->> 'lead_days')::smallint,
        (entry ->> 'minors_only')::boolean,
        (entry ->> 'confidence')::public.travel_confidence,
        entry ->> 'source_url',
        (entry ->> 'checked_on')::date
      );
      pos := pos + 1;
      lines_written := lines_written + 1;
    end loop;
  end loop;

  raise notice 'Travel routes: % added, % rewritten, % left alone; % lines written', added, updated, kept, lines_written;
end;
$do$;
